# Archive the sheet (SHEET_ARCHIVED): only a steward may, and only once; afterwards every change to it is refused (400).
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplySheetArchived
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveSheet
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.sheet.AuditSheetArchived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
# Load a sheet by id: a sheet never loaded before is created empty.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetRequest
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
handle:
  class: net.officefloor.hq.app.sheet.HandleSheetArchived
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Archives the sheet; only a steward (given or delegated) may. */
public class ApplySheetArchived {
    public void apply(@Val Sheet sheet, @RequestParam("user") String user, SettingRepository settings,
            Out<Sheet> updated) throws SheetArchivedException {
        if (settings.find(sheet.id()).roleOf(user) != Role.STEWARD) {
            throw new SheetArchivedException("Only a steward can archive the sheet.");
        }
        updated.set(new Sheet(sheet.id(), sheet.today(), true));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the sheet just archived. */
public class AuditSheetArchived {
    public void audit(@Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        audit.record("SHEET_ARCHIVED sheet=" + sheet.id() + " by=" + user);
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Refuses (400) any change to an archived sheet: it runs first, so a refused change writes nothing. */
public class CheckNotArchived {
    public void check(@PathVariable("sheetId") String sheetId, SheetRepository sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId)) {
            throw new SheetArchivedException("An archived sheet cannot be changed.");
        }
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleSheetArchived {
    public void handle(@Parameter SheetArchivedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.sheet;

/** A change asked for on an archived sheet, which can no longer be changed. */
public class SheetArchivedException extends Exception {
    public SheetArchivedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheet)
            throws SheetNotFoundException {
        Sheet found = repository.find(sheetId);
        if (found == null) {
            throw new SheetNotFoundException(sheetId);
        }
        sheet.set(found);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class EnsureSheet {
    public void ensure(@Val SheetRequest request, SheetRepository repository, Out<Sheet> sheet) {
        sheet.set(repository.ensure(request.id()));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;

/**
 * A sheet: the unit everything else in the app is kept under. {@code today} is the sheet's own
 * date — every date-dependent decision and every default date uses it, never the real clock.
 * An {@code archived} sheet stays visible but refuses every change.
 */
public record Sheet(String id, LocalDate today, boolean archived) {
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, created empty (today = the real date) when it was never loaded before. */
    public Sheet ensure(String id) {
        jdbc.update("INSERT INTO sheet (id, today, started) SELECT ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                id, Date.valueOf(LocalDate.now()), Date.valueOf(LocalDate.now()), id);
        return find(id);
    }

    /** The sheet with this id, or null when it was never loaded. */
    public Sheet find(String id) {
        List<Sheet> found = jdbc.query("SELECT id, today, archived FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(rs.getString("id"), rs.getDate("today").toLocalDate(), rs.getBoolean("archived")),
                id);
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * The sheet's today. Use this — never {@code LocalDate.now()} — for any date-dependent decision
     * or default date in the sheet.
     */
    public LocalDate today(String id) {
        Sheet sheet = find(id);
        return sheet == null ? LocalDate.now() : sheet.today();
    }

