import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { sheetInfoKey, sheetKey, useCurrentSheet, useCurrentUser } from './session';
import type { SheetInfo } from './session';
import { useSheetInfo, useSheetToday } from './sheetToday';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's own "today": shown, and changed by typing a date and saving. A blank date resets it
// to the real date. A steward can archive the sheet here: an archived sheet refuses every change.
export function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const info = useSheetInfo();
  const [date, setDate] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}/today?user=${encodeURIComponent(user)}`, { today: value }),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetInfoKey(saved.id), saved);
      // Everything that depends on the date is kept under the sheet's key.
      await queryClient.invalidateQueries({ queryKey: sheetKey(saved.id) });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  const archive = useMutation({
    mutationFn: () =>
      postJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}/archive?user=${encodeURIComponent(user)}`, {}),
    onSuccess: (saved) => queryClient.setQueryData(sheetInfoKey(saved.id), saved),
    onError: () => setError('The sheet could not be archived.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = date.trim();
    setError('');
    if (trimmed && !/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(trimmed));
  };

  return (
    <form onSubmit={submit}>
      <span>
        Today: <strong data-testid="sheet-today">{today}</strong>{' '}
      </span>
      <input
        data-testid="sheet-today-input"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      <span>
        {' '}Archived: <strong data-testid="sheet-archived">{info.data ? (info.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      </span>
      <span>
        {' '}Parent: <strong data-testid="sheet-parent">{info.data?.parent ?? ''}</strong>{' '}
      </span>
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          setError('');
          once(() => archive.mutateAsync());
        }}
      >
        Archive sheet
      </button>
      {error && <span data-testid="sheet-error">{error}</span>}
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetInfoKey, useCurrentSheet } from './session';
import type { SheetInfo } from './session';

/**
 * The active sheet's today (yyyy-MM-dd), or '' while it loads. Every date-dependent decision and
 * every default date on screen uses this — never `new Date()`.
 */
export function useSheetToday(): string {
  return useSheetInfo().data?.today ?? '';
}

/** The active sheet as the store holds it (its id, today and whether it is archived). */
export function useSheetInfo() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetInfoKey(sheet),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}`),
    enabled: !!sheet,
  });
}
import { AppHeader } from '../../slots/defs/appHeader';
import { AsOf } from './AsOf';
import { SheetPicker } from './SheetPicker';
import { SheetToday } from './SheetToday';
import { SignIn } from './SignIn';

export const contributions = [
  AppHeader.fill({ order: 0, Component: SignIn }),
  AppHeader.fill({ order: 10, Component: SheetPicker }),
  AppHeader.fill({ order: 20, Component: SheetToday }),
  AppHeader.fill({ order: 25, Component: AsOf }),
];
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a refusal (400) from a conflict with someone else's save (409). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/**
 * The date this screen shows the sheet as of (yyyy-MM-dd), or '' when it shows the sheet now. It is
 * the `asof` search param (features/session/AsOf), read here so every read of the sheet carries it
 * and every change is refused while it is set.
 */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"(.*)"$/, '$1');
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen showing the sheet as of a date changes nothing; loading a sheet is not a change.
  if (init?.method && init.method !== 'GET' && path !== '/api/sheets' && currentAsOf()) {
    throw new HttpError(`${init.method} ${path} refused: the sheet is shown as of ${currentAsOf()}`, 400);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  const asOf = currentAsOf();
  if (asOf && path.startsWith('/api/sheets/')) {
    return send<T>(`${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`);
  }
  return send<T>(path);
}

/** Read the store as it holds it now, even while the screen shows the sheet as of a date. */
export function getLiveJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useCallback, useRef } from 'react';

/**
 * Runs a submit only when the one before it has answered, so a double click (two submits before
 * the button re-renders disabled) stores one record, not two. Pass a mutation's `mutateAsync`
 * call; its own onError shows any refusal.
 */
export function useOneAtATime() {
  const busy = useRef(false);
  return useCallback((start: () => Promise<unknown>) => {
    if (busy.current) return;
    busy.current = true;
    start()
      .catch(() => undefined)
      .finally(() => {
        busy.current = false;
      });
  }, []);
}

