  class: net.officefloor.hq.app.sheet.HandleSheetCloneRefused
EOF
cat > 'resources/officefloor/rest/api/sheets/{sheetId}/clone.POST.yml' <<'EOF'
# Clone the sheet to another id (SHEET_CLONE_MADE here; SHEET_CLONED, then its rollup, on the clone). Anyone but a
# steward, or a sheet already used, is refused (400). See SheetCloner for what the clone gets.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetCloneRequest
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.sheet.CheckSheetClone
  govern: [ transaction ]
  next: clone
clone:
  class: net.officefloor.hq.app.sheet.CloneSheet
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.sheet.AuditSheetCloned
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheetClone
  govern: [ transaction ]
EOF

